 * *ncolorsP is left unchanged. */
void make_random_colormap(Screen *, Visual *, Colormap, XColor *colors,
                          int *ncolorsP, Bool bright_p, Bool allocate_p,
                          Bool *writable_pP, Bool verbose_p);

